/bin/bash -lc "node --input-type=module <<'NODE'
import assert from 'node:assert/strict'
import { readFileSync } from 'node:fs'
const origin = 'http://127.0.0.1:3000'
async function html(path, status = 200, agent = 'AppRouterMigrationTest') {
  const response = await fetch(origin + path, { headers: { 'User-Agent': agent } })
  assert.equal(response.status, status, path)
  return response.text()
}
const home = await html('/')
assert.match(home, /Welcome to My Blog/)
assert.match(home, /AppRouterMigrationTest/)
assert.match(home, /<title>Home - My Blog<\\/title>/)
assert.match(home, /property=\"og:title\" content=\"Home - My Blog\"/)
const secondHome = await html('/', 200, 'SecondRequestAgent')
assert.match(secondHome, /SecondRequestAgent/)
assert.doesNotMatch(secondHome, /AppRouterMigrationTest/)
assert.notEqual(home.match(/\\d{4}-\\d{2}-\\d{2}T[\\d:.]+Z/)[0], secondHome.match(/\\d{4}-\\d{2}-\\d{2}T[\\d:.]+Z/)[0])
const blog = await html('/blog')
assert.match(blog, /<title>Blog - My Blog<\\/title>/)
assert.equal((blog.match(/class=\"post-card\"/g) ?? []).length, 100)
for (const id of [1, 11]) {
  const post = await html("'`/blog/${id}`)
  assert.match(post, /Comments '"\\(<"'!-- -->5<!-- -->'"\\)/)
  assert.match(post, /property=\"og:title\"/)
  assert.match(post, /<article>/)
}
const missing = await html('/missing-route', 404)
assert.match(missing, /<title>404 - Page Not Found<\\/title>/)
assert.match(missing, /Go Back Home/)
const missingPost = await html('/blog/999999', 404, 'Googlebot')
assert.match(missingPost, /404 - Page Not Found/)
assert.match(missingPost, /name=\"robots\" content=\"noindex\"/)
const collection = await fetch(origin + '/api/posts')
assert.equal(collection.status, 200)
assert.equal((await collection.json()).length, 2)
const created = await fetch(origin + '/api/posts', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ title: 'Smoke title', content: 'Smoke body' }) })
assert.equal(created.status, 201)
assert.equal((await created.json()).title, 'Smoke title')
const updated = await fetch(origin + '/api/posts/42', { method: 'PUT', headers: { 'Content-Type': 'application/json' }, body: '{}' })
assert.equal(updated.status, 200)
assert.equal((await updated.json()).content, 'Updated content for post 42')
const deleted = await fetch(origin + '/api/posts/42', { method: 'DELETE' })
assert.equal(deleted.status, 200)
assert.equal((await deleted.json()).message, 'Post 42 deleted successfully')
for (const path of ['/api/posts', '/api/posts/42']) {
  const unsupported = await fetch(origin + path, { method: 'PATCH' })
  assert.equal(unsupported.status, 405)
  const options = await fetch(origin + path, { method: 'OPTIONS' })
  assert.equal(options.status, 204)
  assert.match(options.headers.get('allow'), /GET/)
}
const manifest = JSON.parse(readFileSync('.next/prerender-manifest.json', 'utf8'))
assert.equal(manifest.routes['/blog'].initialRevalidateSeconds, 60)
assert.equal(manifest.routes['/blog/1'].initialRevalidateSeconds, 300)
assert.equal(Object.keys(manifest.routes).filter(path => /"'^'"\\/blog\\/\\d+"'$/.test(path)).length, 10)
assert.equal(manifest.routes['"'/'], undefined)
console.log('Production smoke checks passed: SSR, metadata, 100-post index, prebuilt and on-demand posts, 404s, API methods, and ISR settings.')
NODE"

